package com.example.shop.domain.service.impl;

import com.example.shop.api.dto.*;
import com.example.shop.domain.exception.*;
import com.example.shop.domain.model.*;
import com.example.shop.domain.repository.OrderRepository;
import com.example.shop.domain.service.OrderService;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.List;
import java.util.stream.Collectors;

@Service
@RequiredArgsConstructor
@Transactional
public class OrderServiceImpl implements OrderService {

    private final OrderRepository orderRepository;

    @Override
    public OrderResponse create(OrderRequest request) {
        Order order = Order.builder()
            .customerName(request.customerName())
            .status(OrderStatus.PENDING)
            .build();

        List<OrderItem> items = request.items().stream()
            .map(itemReq -> OrderItem.builder()
                .productName(itemReq.productName())
                .quantity(itemReq.quantity())
                .price(itemReq.price())
                .order(order)
                .build())
            .collect(Collectors.toList());

        order.setItems(items);
        order.setTotal(items.stream()
            .map(OrderItem::getSubtotal)
            .reduce(BigDecimal.ZERO, BigDecimal::add));

        Order saved = orderRepository.save(order);
        return toResponse(saved);
    }

    @Override
    @Transactional(readOnly = true)
    public OrderResponse findById(Long id) {
        Order order = orderRepository.findById(id)
            .orElseThrow(() -> new OrderNotFoundException(id));
        return toResponse(order);
    }

    @Override
    @Transactional(readOnly = true)
    public List<OrderResponse> findAll() {
        return orderRepository.findAll().stream()
            .map(this::toResponse)
            .collect(Collectors.toList());
    }

    @Override
    public OrderResponse update(Long id, OrderUpdateRequest request) {
        Order order = orderRepository.findById(id)
            .orElseThrow(() -> new OrderNotFoundException(id));

        if (order.getStatus() == OrderStatus.SHIPPED || 
            order.getStatus() == OrderStatus.DELIVERED) {
            throw new InvalidOrderStateException(
                "Cannot update order in status: " + order.getStatus());
        }

        if (request.customerName() != null) {
            order.setCustomerName(request.customerName());
        }

        Order saved = orderRepository.save(order);
        return toResponse(saved);
    }

    @Override
    public void delete(Long id) {
        if (!orderRepository.existsById(id)) {
            throw new OrderNotFoundException(id);
        }
        orderRepository.deleteById(id);
    }

    @Override
    public OrderResponse cancel(Long id) {
        Order order = orderRepository.findById(id)
            .orElseThrow(() -> new OrderNotFoundException(id));

        if (order.getStatus() == OrderStatus.SHIPPED || 
            order.getStatus() == OrderStatus.DELIVERED) {
            throw new InvalidOrderStateException(
                "Cannot cancel order in status: " + order.getStatus());
        }

        order.setStatus(OrderStatus.CANCELLED);
        Order saved = orderRepository.save(order);
        return toResponse(saved);
    }

    private OrderResponse toResponse(Order order) {
        List<OrderItemResponse> items = order.getItems().stream()
            .map(item -> new OrderItemResponse(
                item.getId(),
                item.getProductName(),
                item.getQuantity(),
                item.getPrice(),
                item.getSubtotal()))
            .collect(Collectors.toList());

        return new OrderResponse(
            order.getId(),
            order.getCustomerName(),
            order.getStatus().name(),
            order.getTotal(),
            items,
            order.getCreatedAt(),
            order.getUpdatedAt());
    }
}

