package com.example.shop.domain.service;

import com.example.shop.api.dto.*;
import com.example.shop.domain.exception.OrderNotFoundException;
import com.example.shop.domain.model.*;
import com.example.shop.domain.repository.OrderRepository;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.List;
import java.util.Optional;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class OrderServiceImplTest {

    @Mock
    private OrderRepository orderRepository;

    @InjectMocks
    private OrderServiceImpl orderService;

    private OrderRequest validRequest;
    private Order savedOrder;

    @BeforeEach
    void setUp() {
        validRequest = new OrderRequest(
            "John Doe",
            "john@example.com",
            List.of(
                new OrderRequest.OrderItemRequest("Laptop", 1, new BigDecimal("999.99")),
                new OrderRequest.OrderItemRequest("Mouse", 2, new BigDecimal("29.99"))));

        savedOrder = Order.builder()
            .id(1L)
            .customerName("John Doe")
            .customerEmail("john@example.com")
            .status(OrderStatus.PENDING)
            .total(new BigDecimal("1059.97"))
            .items(List.of(
                OrderItem.builder().id(1L).productName("Laptop")
                    .quantity(1).price(new BigDecimal("999.99")).build(),
                OrderItem.builder().id(2L).productName("Mouse")
                    .quantity(2).price(new BigDecimal("29.99")).build()))
            .createdAt(LocalDateTime.now())
            .updatedAt(LocalDateTime.now())
            .build();
    }

    @Test
    void shouldCreateOrderSuccessfully() {
        when(orderRepository.save(any(Order.class))).thenReturn(savedOrder);

        OrderResponse response = orderService.create(validRequest);

        assertThat(response).isNotNull();
        assertThat(response.customerName()).isEqualTo("John Doe");
        assertThat(response.status()).isEqualTo("PENDING");
        verify(orderRepository, times(1)).save(any(Order.class));
    }

    @Test
    void shouldThrowExceptionWhenOrderNotFound() {
        when(orderRepository.findById(999L)).thenReturn(Optional.empty());

        assertThatThrownBy(() -> orderService.findById(999L))
            .isInstanceOf(OrderNotFoundException.class)
            .hasMessageContaining("999");

        verify(orderRepository, never()).save(any());
    }

    @Test
    void shouldReturnOrderWhenExists() {
        when(orderRepository.findById(1L)).thenReturn(Optional.of(savedOrder));

        OrderResponse response = orderService.findById(1L);

        assertThat(response.id()).isEqualTo(1L);
        assertThat(response.total()).isEqualByComparingTo(new BigDecimal("1059.97"));
    }
}

