@Service
@RequiredArgsConstructor
@Slf4j
public class AuthServiceImpl implements AuthService {

    private final AuthenticationManager authenticationManager;
    private final JwtService jwtService;
    private final RefreshTokenRepository refreshTokenRepository;
    private final PasswordEncoder passwordEncoder;
    private final UserRepository userRepository;

    @Override
    public AuthResponse login(LoginRequest request) {
        Authentication authentication = authenticationManager.authenticate(
            new UsernamePasswordAuthenticationToken(
                request.email(), request.password()));

        SecurityContextHolder.getContext().setAuthentication(authentication);

        UserDetails userDetails = (UserDetails) authentication.getPrincipal();

        String accessToken = jwtService.generateAccessToken(userDetails);
        String refreshToken = jwtService.generateRefreshToken(userDetails);

        // Store refresh token in database
        RefreshToken token = RefreshToken.builder()
            .token(refreshToken)
            .userEmail(userDetails.getUsername())
            .expiryDate(Instant.now().plus(Duration.ofDays(7)))
            .build();
        refreshTokenRepository.save(token);

        log.info("User {} authenticated successfully", request.email());

        return new AuthResponse(accessToken, refreshToken, "Bearer", 3600);
    }

    @Override
    public AuthResponse refreshToken(RefreshTokenRequest request) {
        RefreshToken refreshToken = refreshTokenRepository
            .findByToken(request.refreshToken())
            .orElseThrow(() -> new InvalidTokenException("Refresh token not found"));

        if (refreshToken.getExpiryDate().isBefore(Instant.now())) {
            refreshTokenRepository.delete(refreshToken);
            throw new InvalidTokenException("Refresh token expired");
        }

        String userEmail = refreshToken.getUserEmail();
        UserDetails userDetails = userRepository.findByEmail(userEmail)
            .orElseThrow(() -> new UserNotFoundException(userEmail));

        String newAccessToken = jwtService.generateAccessToken(userDetails);
        String newRefreshToken = jwtService.generateRefreshToken(userDetails);

        // Rotate refresh token
        refreshTokenRepository.delete(refreshToken);
        RefreshToken newToken = RefreshToken.builder()
            .token(newRefreshToken)
            .userEmail(userEmail)
            .expiryDate(Instant.now().plus(Duration.ofDays(7)))
            .build();
        refreshTokenRepository.save(newToken);

        return new AuthResponse(newAccessToken, newRefreshToken, "Bearer", 3600);
    }
}

