    private final RedisTemplate<String, String> redisTemplate;
    private static final String BLACKLIST_PREFIX = "token:blacklist:";

    public void blacklist(String token, long expirationMs) {
        redisTemplate.opsForValue().set(
            BLACKLIST_PREFIX + token,
            "blocked",
            expirationMs,
            TimeUnit.MILLISECONDS
        );
    }

    public boolean isBlacklisted(String token) {
        return Boolean.TRUE.equals(
            redisTemplate.hasKey(BLACKLIST_PREFIX + token));
    }

    public void blacklistAccessToken(String token, long expirationMs) {
        blacklist("access:" + token, expirationMs);
    }

    public void blacklistRefreshToken(String token, long expirationMs) {
        blacklist("refresh:" + token, expirationMs);
    }

    public boolean isAccessTokenBlacklisted(String token) {
        return isBlacklisted("access:" + token);
    }

    public boolean isRefreshTokenBlacklisted(String token) {
        return isBlacklisted("refresh:" + token);
    }
}

