package com.example.shop.domain.service;

import com.example.shop.api.dto.*;
import com.example.shop.domain.exception.*;
import com.example.shop.domain.model.Product;
import com.example.shop.domain.repository.ProductRepository;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import java.math.BigDecimal;
import java.util.List;
import java.util.Optional;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class ProductServiceTest {

    @Mock
    private ProductRepository productRepository;

    @InjectMocks
    private ProductServiceImpl productService;

    private Product sampleProduct;

    @BeforeEach
    void setUp() {
        sampleProduct = Product.builder()
            .id(1L)
            .name("Test Product")
            .description("A test product")
            .price(new BigDecimal("29.99"))
            .category("ELECTRONICS")
            .stock(100)
            .build();
    }

    @Test
    void create_shouldSaveAndReturnProduct() {
        when(productRepository.save(any(Product.class))).thenReturn(sampleProduct);

        ProductResponse response = productService.create(
            new ProductRequest("Test Product", "A test product",
                new BigDecimal("29.99"), "ELECTRONICS", 100));

        assertThat(response).isNotNull();
        assertThat(response.name()).isEqualTo("Test Product");
        verify(productRepository).save(any(Product.class));
    }

    @Test
    void findById_shouldReturnProduct() {
        when(productRepository.findById(1L)).thenReturn(Optional.of(sampleProduct));

        ProductResponse response = productService.findById(1L);

        assertThat(response.id()).isEqualTo(1L);
        assertThat(response.price()).isEqualByComparingTo(new BigDecimal("29.99"));
    }

    @Test
    void findById_shouldThrowWhenNotFound() {
        when(productRepository.findById(999L)).thenReturn(Optional.empty());

        assertThatThrownBy(() -> productService.findById(999L))
            .isInstanceOf(ProductNotFoundException.class);
    }

    @Test
    void findByCategory_shouldReturnList() {
        when(productRepository.findByCategory("ELECTRONICS"))
            .thenReturn(List.of(sampleProduct));

        List<ProductResponse> results = productService.findByCategory("ELECTRONICS");

        assertThat(results).hasSize(1);
        assertThat(results.get(0).category()).isEqualTo("ELECTRONICS");
    }

    @Test
    void updatePrice_shouldUpdateAndReturn() {
        when(productRepository.findById(1L)).thenReturn(Optional.of(sampleProduct));
        sampleProduct.setPrice(new BigDecimal("39.99"));
        when(productRepository.save(any(Product.class))).thenReturn(sampleProduct);

        ProductResponse response = productService.updatePrice(1L, new BigDecimal("39.99"));

        assertThat(response.price()).isEqualByComparingTo(new BigDecimal("39.99"));
    }

    @Test
    void updatePrice_shouldThrowWhenNegative() {
        assertThatThrownBy(() -> productService.updatePrice(1L, new BigDecimal("-10")))
            .isInstanceOf(ValidationException.class)
            .hasMessageContaining("negative");
    }

    @Test
    void delete_shouldRemoveProduct() {
        when(productRepository.existsById(1L)).thenReturn(true);

        productService.delete(1L);

        verify(productRepository).deleteById(1L);
    }

    @Test
    void delete_shouldThrowWhenNotFound() {
        when(productRepository.existsById(999L)).thenReturn(false);

        assertThatThrownBy(() -> productService.delete(999L))
            .isInstanceOf(ProductNotFoundException.class);

        verify(productRepository, never()).deleteById(any());
    }
}

