// Interfaz de estrategia
public interface PricingStrategy {
    BigDecimal calculateDiscount(BigDecimal total, Customer customer);
    String getStrategyName();
}

// Estrategias concretas
@Component
public class NoDiscountStrategy implements PricingStrategy {
    @Override
    public BigDecimal calculateDiscount(BigDecimal total, Customer customer) {
        return BigDecimal.ZERO;
    }

    @Override
    public String getStrategyName() {
        return "NO_DISCOUNT";
    }
}

@Component
public class PercentageDiscountStrategy implements PricingStrategy {
    @Override
    public BigDecimal calculateDiscount(BigDecimal total, Customer customer) {
        if (customer.isPremium()) {
            return total.multiply(new BigDecimal("0.10")); // 10% off
        }
        return total.multiply(new BigDecimal("0.05")); // 5% off
    }

    @Override
    public String getStrategyName() {
        return "PERCENTAGE_DISCOUNT";
    }
}

@Component
public class FixedAmountDiscountStrategy implements PricingStrategy {
    private final BigDecimal threshold = new BigDecimal("100.00");
    private final BigDecimal discount = new BigDecimal("15.00");

    @Override
    public BigDecimal calculateDiscount(BigDecimal total, Customer customer) {
        if (total.compareTo(threshold) >= 0) {
            return discount;
        }
        return BigDecimal.ZERO;
    }

    @Override
    public String getStrategyName() {
        return "FIXED_AMOUNT_DISCOUNT";
    }
}

// Contexto que usa la estrategia
@Service
@RequiredArgsConstructor
public class PricingService {

    private final Map<String, PricingStrategy> strategies;

    public PricingService(List<PricingStrategy> strategyList) {
        this.strategies = strategyList.stream()
            .collect(Collectors.toMap(
                PricingStrategy::getStrategyName,
                Function.identity()));
    }

    public BigDecimal calculateFinalPrice(BigDecimal total, Customer customer, 
                                           String strategyName) {
        PricingStrategy strategy = strategies.get(strategyName);
        if (strategy == null) {
            throw new IllegalArgumentException("Unknown strategy: " + strategyName);
        }
        BigDecimal discount = strategy.calculateDiscount(total, customer);
        return total.subtract(discount);
    }
}

