// Interfaz del observer
public interface EventListener {
    void handle(DomainEvent event);
    boolean supports(Class<?> eventType);
}

// Observadores concretos
@Component
@Slf4j
public class InventoryEventListener implements EventListener {

    private final InventoryService inventoryService;

    @Override
    public void handle(DomainEvent event) {
        if (event instanceof OrderCreatedEvent orderEvent) {
            log.info("Updating inventory for order: {}", orderEvent.getAggregateId());
            orderEvent.getProductNames().forEach(product -> 
                inventoryService.decrementStock(product, 1));
        }
    }

    @Override
    public boolean supports(Class<?> eventType) {
        return OrderCreatedEvent.class.isAssignableFrom(eventType);
    }
}

@Component
@Slf4j
public class EmailEventListener implements EventListener {

    private final EmailService emailService;

    @Override
    public void handle(DomainEvent event) {
        if (event instanceof OrderCreatedEvent orderEvent) {
            log.info("Sending confirmation email for order: {}", orderEvent.getAggregateId());
            emailService.sendOrderConfirmation(
                orderEvent.getCustomerName(),
                orderEvent.getAggregateId(),
                orderEvent.getTotal());
        }
    }

    @Override
    public boolean supports(Class<?> eventType) {
        return OrderCreatedEvent.class.isAssignableFrom(eventType);
    }
}

// Event publisher
@Component
@Slf4j
public class EventPublisher {

    private final List<EventListener> listeners;

    public EventPublisher(List<EventListener> listeners) {
        this.listeners = listeners;
    }

    public void publish(DomainEvent event) {
        log.info("Publishing event: {} for aggregate: {}", 
            event.getClass().getSimpleName(), event.getAggregateId());

        listeners.stream()
            .filter(listener -> listener.supports(event.getClass()))
            .forEach(listener -> {
                try {
                    listener.handle(event);
                } catch (Exception e) {
                    log.error("Error handling event {}", event.getClass().getSimpleName(), e);
                }
            });
    }
}

// Interfaz del producto
public interface Notification {
    void send(String recipient, String message);
    String getChannel();
}

// Productos concretos
@Component
public class EmailNotification implements Notification {

    private final JavaMailSender mailSender;

    @Override
    public void send(String recipient, String message) {
        SimpleMailMessage mail = new SimpleMailMessage();
        mail.setTo(recipient);
        mail.setSubject("Notification");
        mail.setText(message);
        mailSender.send(mail);
    }

    @Override
    public String getChannel() {
        return "EMAIL";
    }
}

@Component
public class SmsNotification implements Notification {

    private final TwilioRestClient twilioClient;

    @Override
    public void send(String recipient, String message) {
        MessageCreator creator = Message.creator(
            new PhoneNumber(recipient),
            new PhoneNumber("+1234567890"),
            message);
        creator.create();
    }

    @Override
    public String getChannel() {
        return "SMS";
    }
}

@Component
public class PushNotification implements Notification {

    private final FirebaseMessaging firebaseMessaging;

    @Override
    public void send(String recipient, String message) {
        Message fcmMessage = Message.builder()
            .setToken(recipient)
            .setNotification(com.google.firebase.messaging.Notification.builder()
                .setTitle("Notification")
                .setBody(message)
                .build())
            .build();
        try {
            firebaseMessaging.send(fcmMessage);
        } catch (FirebaseMessagingException e) {
            throw new NotificationException("Failed to send push notification", e);
        }
    }

    @Override
    public String getChannel() {
        return "PUSH";
    }
}

// Factory
@Component
public class NotificationFactory {

    private final Map<String, Notification> notifications;

    public NotificationFactory(List<Notification> notificationList) {
        this.notifications = notificationList.stream()
            .collect(Collectors.toMap(
                Notification::getChannel,
                Function.identity()));
    }

    public Notification create(String channel) {
        Notification notification = notifications.get(channel.toUpperCase());
        if (notification == null) {
            throw new IllegalArgumentException("Unknown notification channel: " + channel);
        }
        return notification;
    }

    public Set<String> getAvailableChannels() {
        return notifications.keySet();
    }
}

// Uso del factory
@Service
@RequiredArgsConstructor
public class NotificationService {

    private final NotificationFactory factory;

    public void sendNotification(String channel, String recipient, String message) {
        Notification notification = factory.create(channel);
        notification.send(recipient, message);
    }

    public void sendOrderUpdate(String channel, String recipient, 
                                  String orderId, String status) {
        String message = String.format(
            "Your order %s has been updated to status: %s", orderId, status);
        sendNotification(channel, recipient, message);
    }
}

