package com.example.shop.payment;

import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;

@Service
@Slf4j
public class PaymentProcessor {

    private final Map<String, PaymentStrategy> strategies;

    public PaymentProcessor(List<PaymentStrategy> strategyList) {
        this.strategies = strategyList.stream()
            .collect(Collectors.toMap(
                PaymentStrategy::getPaymentMethod,
                Function.identity()));
    }

    public PaymentResult processPayment(String method, BigDecimal amount, 
                                         PaymentDetails details) {
        PaymentStrategy strategy = strategies.get(method.toUpperCase());
        if (strategy == null) {
            throw new IllegalArgumentException("Unsupported payment method: " + method);
        }

        log.info("Processing {} payment for amount: {}", method, amount);
        return strategy.pay(amount, details);
    }

    public boolean isPaymentMethodSupported(String method) {
        return strategies.containsKey(method.toUpperCase());
    }
}

